THEME = ("T04", "Intégrité et conflits d'intérêts (Biba, Clark-Wilson, Muraille de Chine)")
SOURCE = "Biba, « Integrity Considerations for Secure Computer Systems », MITRE, 1977 ; Clark et Wilson, « A Comparison of Commercial and Military Computer Security Policies », IEEE, 1987 ; Brewer et Nash, « The Chinese Wall Security Policy », 1989 ⚠ à vérifier"
Q = [
(1,"Quelle propriété le modèle de Biba protège-t-il ?","L'intégrité","La confidentialité","La disponibilité","L'anonymat",
 "Biba (1977) est le pendant de Bell-LaPadula pour l'intégrité."),
(1,"Quelle règle énonce la propriété d'intégrité simple de Biba ?","Pas de lecture vers le bas (no read down)","Pas de lecture vers le haut","Pas d'écriture vers le bas","Pas d'écriture vers le haut",
 "Un sujet ne lit pas de données moins fiables que lui, pour ne pas se corrompre."),
(1,"Quelle règle énonce la propriété d'intégrité étoile de Biba ?","Pas d'écriture vers le haut (no write up)","Pas d'écriture vers le bas","Pas de lecture vers le haut","Pas d'exécution vers le bas",
 "Un sujet de faible intégrité ne modifie pas un objet de forte intégrité."),
(1,"Dans Biba, un stagiaire (intégrité basse) veut modifier une donnée de paie (intégrité haute). Résultat ?","Refusé : écriture vers le haut","Permis : écriture vers le haut","Refusé : lecture vers le haut","Permis si le stagiaire est propriétaire",
 "La règle « no write up » protège la donnée haute contre un sujet moins fiable."),
(2,"Dans Biba, le logiciel de paie (intégrité haute) importe un fichier de provenance inconnue (intégrité basse). Résultat ?","Refusé : lecture vers le bas","Permis : lecture vers le bas","Refusé : écriture vers le haut","Permis sans condition",
 "Lire une donnée peu fiable risque de contaminer la donnée haute : « no read down »."),
(2,"Comparées à BLP, les règles de Biba sont :","Symétriques, le sens des interdictions est inversé","Identiques","Sans rapport","Limitées à la lecture",
 "BLP : pas de lecture haute, pas d'écriture basse ; Biba : pas de lecture basse, pas d'écriture haute."),
(2,"Quel est l'inconvénient de Biba strict en pratique ?","Il est très restrictif et difficile à appliquer sur des systèmes réels","Il ne protège rien","Il n'a aucun niveau","Il chiffre les fichiers",
 "Beaucoup de flux utiles viennent de sources de niveau plus bas, d'où des variantes plus souples."),
(3,"Que fait la politique « low-water mark » de Biba ?","Elle abaisse le niveau d'un sujet qui lit une donnée de niveau inférieur","Elle augmente le niveau des fichiers","Elle supprime les écritures","Elle chiffre les lectures",
 "Le sujet peut lire plus bas mais il devient moins fiable : le niveau suit le plus bas qu'il a lu."),
(2,"Quel modèle d'intégrité est conçu pour les applications commerciales avec transactions ?","Clark-Wilson","Bell-LaPadula","Brewer-Nash","HRU",
 "Clark et Wilson (1987) ont proposé une politique pour les données financières et comptables."),
(2,"Dans Clark-Wilson, que sont les CDI ?","Les données dont l'intégrité doit être protégée","Les certificats d'identité","Les chiffres de disponibilité","Les contrôles d'intrusion",
 "Constrained Data Items : les données contraintes, accessibles seulement par des procédures validées."),
(2,"Dans Clark-Wilson, que sont les UDI ?","Des données non contraintes, avant validation (par exemple la saisie)","Des données chiffrées","Des utilisateurs distants","Des unités de disque",
 "Unconstrained Data Items : entrées non contrôlées, à valider avant de devenir des CDI."),
(2,"Dans Clark-Wilson, que sont les TP ?","Les procédures de transformation, seules habilitées à modifier les CDI","Les tests de pénétration","Les types de protocole","Les tableaux de privilèges",
 "Transformation Procedures : programmes certifiés qui conservent l'intégrité."),
(2,"Dans Clark-Wilson, quel est le rôle des IVP ?","Vérifier que les CDI sont dans un état cohérent","Gérer les mots de passe","Chiffrer les CDI","Créer des utilisateurs",
 "Integrity Verification Procedures : elles contrôlent la cohérence avant et après les transformations."),
(2,"Quel triplet caractérise le contrôle d'accès de Clark-Wilson ?","Utilisateur, procédure de transformation, donnée contrainte","Sujet, niveau, catégorie","Rôle, session, permission","Attribut, environnement, ressource",
 "Un utilisateur n'agit sur un CDI que via un TP pour lequel il est autorisé."),
(2,"Pourquoi Clark-Wilson autorise-t-il un utilisateur à exécuter un TP plutôt qu'à modifier directement un CDI ?","Le TP garantit des modifications valides et cohérentes","Le TP est plus rapide","Le CDI est chiffré","Le TP est anonyme",
 "L'utilisateur n'a pas d'accès direct : toute modification passe par des procédures certifiées."),
(3,"Quelle règle de Clark-Wilson impose la séparation des tâches ?","Les triplets doivent répartir l'exécution entre plusieurs utilisateurs","Les TP sont chiffrés","Les UDI sont supprimés","Le CDI est public",
 "Par exemple, celui qui saisit un virement ne doit pas être celui qui le valide."),
(3,"Quel rôle joue le journal (audit) dans Clark-Wilson ?","Enregistrer les TP pour reconstituer et vérifier les opérations","Remplacer les mots de passe","Supprimer les UDI","Chiffrer les CDI",
 "Un CDI spécial append-only conserve les traces de toutes les transformations."),
(2,"Quelle situation illustre le mieux l'application de Clark-Wilson ?","Une écriture comptable validée par un workflow à deux personnes","Un fichier public partagé","Un mot de passe commun","Un compte invité",
 "Saisie par l'un, validation par l'autre, avec vérification de cohérence."),
(2,"Quel est le point fort de Clark-Wilson par rapport à Biba ?","Il intègre des procédures certifiées et la séparation des tâches","Il est plus simple","Il n'a pas besoin de journal","Il n'utilise pas d'utilisateurs",
 "Il traite l'intégrité sous l'angle des processus métiers, pas seulement des niveaux."),
(1,"À quel risque le modèle de la Muraille de Chine répond-il ?","Un conflit d'intérêts entre clients concurrents","Une coupure réseau","Une surcharge disque","Une perte de mot de passe",
 "Brewer et Nash (1989) l'ont conçu pour les cabinets de conseil et d'audit."),
(2,"Dans la Muraille de Chine, que sont les classes de conflit d'intérêts ?","Des groupes d'entreprises concurrentes dont les données ne doivent pas être mêlées","Des classes de salles","Des niveaux de mot de passe","Des types de câbles",
 "Un consultant qui a vu les données d'une banque ne doit plus accéder à celles d'une banque concurrente."),
(2,"Dans la Muraille de Chine, que se passe-t-il après qu'un consultant a lu les données de la banque A ?","Il ne peut plus lire celles de la banque B si elles sont concurrentes","Il peut tout lire","Il perd son compte","Il peut seulement écrire",
 "Les droits dépendent de l'historique des accès : le modèle est dynamique."),
(2,"Pourquoi la Muraille de Chine est-elle dite dynamique ?","Les droits changent selon les accès déjà réalisés","Elle utilise des animations","Elle change de mot de passe","Elle est en ligne",
 "Chaque lecture peut fermer l'accès à d'autres données."),
(2,"Quel métier est le plus concerné par la Muraille de Chine ?","Conseil financier et audit","Imprimerie","Transport routier uniquement","Fabrication de meubles",
 "Les cabinets doivent éviter d'utiliser les informations d'un client au profit d'un concurrent."),
(3,"Un consultant a lu des données de la banque A (classe Banques). Peut-il lire des données de l'assureur C (classe Assurances) ?","Oui : classe de conflit différente","Non : il a déjà lu une banque","Non : toute lecture est unique","Oui, mais sans écrire",
 "Seules les entreprises de la même classe de conflit sont exclues."),
(3,"Pourquoi la Muraille de Chine impose-t-elle aussi une règle sur l'écriture ?","Pour éviter qu'un consultant ne fasse passer l'information d'un client à un autre en écrivant","Pour accélérer les écritures","Pour supprimer les lectures","Pour réduire la taille des fichiers",
 "Une écriture n'est permise que si le sujet n'a lu que des données du même client ou non concurrentes."),
(2,"Quelle propriété de sécurité la Muraille de Chine protège-t-elle d'abord ?","La confidentialité entre concurrents","La disponibilité","La performance","L'anonymat",
 "Le modèle est fondé sur l'historique pour limiter la fuite d'informations d'entreprises concurrentes."),
(2,"Quelle structure de données la Muraille de Chine utilise-t-elle ?","Ensembles de données de société, classes de conflit et historique des accès","Arbre de rôles","Treillis de niveaux seulement","Annuaires X.500 seulement",
 "Trois niveaux : objets, ensembles de données d'une société, classes de conflit."),
(1,"Quelle mesure technique protège contre la modification accidentelle d'une donnée par un utilisateur non habilité ?","Les droits d'écriture limités","La lecture seule universelle","La suppression du mot de passe","Le partage de compte",
 "Réduire l'écriture au nécessaire protège l'intégrité."),
(2,"Quelle méthode permet de vérifier qu'un fichier n'a pas été modifié ?","Une empreinte (hash) comparée à une valeur de référence","Un mot de passe","Un pare-feu","Une sauvegarde incrémentale",
 "Une empreinte change si le contenu change : c'est la base des contrôles d'intégrité de fichiers."),
(2,"Pourquoi le journal d'audit doit-il être protégé en écriture seule (append-only) ?","Pour empêcher un attaquant d'effacer ses traces","Pour réduire sa taille","Pour accélérer les connexions","Pour supprimer les doublons",
 "L'intégrité du journal fonde la valeur probante des preuves."),
(3,"Quelle mesure complète le mieux Biba pour protéger l'intégrité des programmes ?","La signature de code et la vérification avant exécution","Un fond d'écran","Une classification Public","La suppression des mises à jour",
 "On n'exécute que des programmes d'intégrité vérifiée."),
(2,"Que garantit un workflow « quatre yeux » ?","Une opération sensible est validée par une deuxième personne","Qu'elle soit plus rapide","Qu'elle soit publique","Qu'elle soit anonyme",
 "Il réalise la séparation des tâches dans les processus métiers."),
(3,"Quelle faiblesse peut subsister dans un workflow à deux validateurs ?","La collusion entre les deux personnes","L'absence de validateur","L'utilisation de journal","La classification",
 "La séparation des tâches ne résiste pas à une entente frauduleuse : d'où rotation, contrôle et audit."),
(2,"Qu'est-ce qu'une transaction bien formée ?","Une transformation qui fait passer les données d'un état valide à un autre état valide","Une transaction très courte","Une transaction chiffrée","Une transaction sans utilisateur",
 "Elle conserve les invariants (par exemple l'équilibre débit et crédit)."),
(3,"En comptabilité en partie double, quel invariant une procédure bien formée doit-elle préserver ?","Le total des débits égale le total des crédits","Le solde est toujours positif","Le nombre d'écritures est pair","Chaque écriture est signée",
 "C'est l'exemple classique de contrainte d'intégrité utilisé par Clark et Wilson."),
(2,"Quelle différence essentielle existe entre Biba et Clark-Wilson ?","Biba raisonne par niveaux, Clark-Wilson par procédures et séparation des tâches","Biba est commercial, Clark-Wilson militaire","Aucune","Clark-Wilson ne protège pas l'intégrité",
 "Clark-Wilson est orienté application métier et ne repose pas sur des étiquettes."),
(2,"Quel moyen détecte une modification non autorisée d'un fichier système ?","Un outil de contrôle d'intégrité de fichiers","Un économiseur d'écran","Un clavier chiffré","Un nouvel écran",
 "Il compare régulièrement les empreintes à une base de référence sûre."),
(2,"Quelle règle permet de limiter les erreurs de saisie avant qu'elles ne deviennent des données validées ?","Valider les UDI par une procédure avant de les transformer en CDI","Interdire la saisie","Supprimer les contrôles","Autoriser tout en écriture",
 "La validation d'entrée protège la qualité de données contraintes."),
(3,"Quel scénario illustre une violation de l'intégrité sans fuite de confidentialité ?","Un employé modifie un RIB fournisseur dans l'ERP","Un employé lit un document Public","Un employé consulte son planning","Un employé change de mot de passe",
 "Les données restent confidentielles mais deviennent fausses : c'est une atteinte à l'intégrité."),
(2,"Quelle mesure empêche un informaticien de modifier lui-même les journaux de ses propres actions ?","Envoi des journaux vers un système distinct qu'il n'administre pas","Journaux en clair sur le même serveur","Suppression des journaux","Partage du mot de passe",
 "La séparation de l'administration des journaux garantit leur fiabilité."),
(3,"Que garantit la propriété « no write up » de Biba pour un opérateur de bas niveau ?","Il ne peut pas altérer les données de niveau supérieur","Il ne peut pas lire","Il peut tout supprimer","Il est administrateur",
 "Le niveau bas ne peut pas contaminer ce qui est plus fiable."),
(2,"Quel niveau d'intégrité attribue-t-on typiquement à un fichier téléchargé d'Internet sans vérification ?","Bas","Très haut","Identique à celui du système","Supérieur à celui des applications",
 "Son origine n'est pas maîtrisée : il ne doit pas modifier de données importantes."),
(3,"Pourquoi Biba et BLP sont-ils difficiles à appliquer simultanément ?","Leurs règles se contredisent dès qu'un même niveau doit protéger confidentialité et intégrité","Ils utilisent le même nom","Ils sont chiffrés","Ils n'ont pas de niveaux",
 "Imposer BLP et Biba sur la même hiérarchie conduit à des sujets enfermés à leur niveau."),
(2,"Quel type d'attaque cible l'intégrité en altérant une valeur en cours de route ?","L'homme du milieu qui modifie un message","L'écoute passive","Le déni de service","L'hameçonnage de curiosité",
 "La modification en transit change les données sans que leur lecture soit nécessaire."),
(2,"Quelle contre-mesure détecte l'altération d'un message en transit ?","Un code d'authentification de message ou une signature","Un fond d'écran","Un mot de passe long","Une sauvegarde",
 "MAC ou signature numérique permettent de vérifier qu'un message n'a pas changé."),
(3,"Pourquoi la règle de Clark-Wilson « les TP doivent être certifiés » est-elle importante ?","Un TP défaillant pourrait corrompre les CDI tout en étant autorisé","Elle réduit les coûts","Elle chiffre les TP","Elle supprime les UDI",
 "L'utilisateur est protégé par les TP, mais les TP eux-mêmes doivent être contrôlés."),
(2,"Quel principe protège le plus contre une fraude interne sur un virement ?","La séparation de la saisie et de la validation","Un mot de passe partagé","Une saisie anonyme","Un compte administrateur unique",
 "Le contrôle croisé réduit le risque qu'une seule personne puisse tromper."),
(1,"Que signifie « intégrité des données » ?","Les données sont exactes et n'ont pas été modifiées de façon non autorisée","Les données sont secrètes","Les données sont toujours disponibles","Les données sont anonymes",
 "C'est l'une des trois propriétés de la triade CID."),
]
